schema_ddl:
CREATE TABLE movimenti_logistici (
    id SERIAL PRIMARY KEY,
    data_consegna DATE NOT NULL,
    massa NUMERIC(10,2) NOT NULL CHECK (massa >= 0),
    destinazione TEXT NOT NULL,
    mittente TEXT NOT NULL
);

CREATE TABLE dettagli_consegna (
    movimento_id INT PRIMARY KEY REFERENCES movimenti_logistici(id),
    stato TEXT NOT NULL CHECK (stato IN ('in_transito', 'consegnato', 'in_attesa')),
    note TEXT,
    data_aggiornamento TIMESTAMP
);
